@webjs:(function(){
  var P = "";
  var ALPHA = "-0123456789ABCDEFGHIJKLMNOPQRSTUWX_abcdefghijklmnopqrstuvwxyz";
  var MAPP  = "BLKJIHGFEDCmnopqrstuvwxyz012345689AMNOPQRSTUVWXYZabcdefghijkl";
  var MAP = {};
  for (var i = 0; i < ALPHA.length; i++) MAP[ALPHA.charAt(i)] = MAPP.charAt(i);
  function decodeImages(images) {
    var core = images.substring(3, images.length - 2);
    var kVx = core.indexOf("Vx"), kP = core.indexOf("pL0");
    if (kVx < 0 || kP < 0) throw new Error("markers not found");
    var head = core.substring(0, kVx);
    var mid  = core.substring(kVx + 2, kP);
    var tail = core.substring(kP + 3);
    var combined = tail + head + mid;
    var s = "", gi = 0;
    for (var i = 0; i < combined.length; i += 7) {
      var ch = combined.substring(i, i + 7);
      s += (gi % 2 === 1) ? ch.split("").reverse().join("") : ch;
      gi++;
    }
    var s1 = "";
    for (var j = 0; j < s.length; j++) {
      var c = s.charAt(j);
      s1 += (MAP[c] !== undefined) ? MAP[c] : c;
    }
    var pad = (4 - (s1.length % 4)) % 4;
    var b64 = s1 + (pad ? "====".substring(0, pad) : "");
    return JSON.parse(atob(b64));
  }
  function shuffle(t, l, u) {
    if (!t || !t.length) return t;
    var d = t.length;
    var ml = (l === null || l === undefined) ? null : Number(l);
    var gu = (u === null || u === undefined) ? null : Number(u);
    if (ml === null || gu === null || !(ml >= 0 && ml <= 4294967295) || !(gu >= 0 && gu <= 4294967295)) return t;
    var D = (40503 << 16) | 31153, R = (34283 << 16) | 51819;
    function mul32(a, b){var ah=Math.floor(a/65536),al=a%65536,bh=Math.floor(b/65536),bl=b%65536;var p00=al*bl,p01=al*bh,p10=ah*bl,p11=ah*bh;var mid=p01+p10+Math.floor(p00/65536);var lo=(p00&0xFFFF)|((mid%65536)<<16);var hi=p11+Math.floor(mid/65536);return {hi:hi>>>0,lo:lo>>>0};}
    function xor64(x,y){return {hi:(x.hi^y.hi)>>>0,lo:(x.lo^y.lo)>>>0};}
    function mod64(x,m){var b16=[x.hi>>>16,x.hi&0xFFFF,x.lo>>>16,x.lo&0xFFFF];var rem=0;for(var i=0;i<4;i++)rem=((rem*65536)%m+b16[i])%m;return rem;}
    var L = mul32(gu, D), V = mul32(d, R);
    var b = mod64(xor64(L, V), d);
    var h = (ml ^ b) >>> 0;
    if (h >= d) return t;
    var arr = t.slice();
    arr.splice(h, 1);
    return arr;
  }
  if (window.__hipReady && window.__hipUrls) {
    var html = "";
    for (var x = 0; x < window.__hipUrls.length; x++) html += "<img src=\"" + window.__hipBase + window.__hipUrls[x] + "\">";
    return html;
  }
  var el = document.querySelector("[data-api-hid]");
  if (!el) { window.__hipReady = true; window.asyncR = "1"; return "<p>未找到 data-api-hid</p>"; }
  var apiHid = el.getAttribute("data-api-hid");
  var xhr = new XMLHttpRequest();
  xhr.open("GET", P + "https://hipapi1.s3file.top/v2/chapter?hid=" + encodeURIComponent(apiHid), true);
  xhr.onload = function() {
    try {
      var data = JSON.parse(xhr.responseText).data;
      var images = data.images;
      var urls = typeof images === "string" ? decodeImages(images) : (images instanceof Array ? images : []);
      urls = urls.filter(function(x){ return typeof x === "string"; });
      urls = shuffle(urls, data.order_id, data.sid);
      var base = "https://hip-tx-1.s3imgs.top";
      if (data.line == 9) {
        var l1s = document.querySelector("[data-chapter-img-base-line1s]");
        var l2s = document.querySelector("[data-chapter-img-base-line2s]");
        if (l1s) base = l1s.getAttribute("data-chapter-img-base-line1s");
        else if (l2s) base = l2s.getAttribute("data-chapter-img-base-line2s");
      } else {
        var b2 = document.querySelector("[data-chapter-img-base]");
        if (b2) base = b2.getAttribute("data-chapter-img-base");
      }
      window.__hipUrls = urls;
      window.__hipBase = P + base;
    } catch(e) { window.__hipErr = String(e); }
    window.__hipReady = true;
    window.asyncR = "1";
  };
  xhr.onerror = function() { window.__hipErr = "xhr_error"; window.__hipReady = true; window.asyncR = "1"; };
  xhr.send();
  return null;
})()
